mapper.select:
select ti.* from TAX_DECLARE_SUM_INFO ti where 1=1
and ti.SUBJECT_NATURE = #{booksetId}
and ti.DECLARE_DATE = #{foreDeclar}

		select t.*
		from TAX_BOK_DETAIL t,
		     (select MAX(tbd.BOOK_ORDER) as bookOrder,
		             tbd.BOOKSET_ID as booksetId,
		             tbd.HAPPEN_DATE as happenDate
		       from TAX_BOK_DETAIL tbd
		       where tbd.book_date <= #{endDate}

		   			and tbd.happen_date >= #{startDate}


		   			and tbd.happen_date <= #{endDate}


		   			and tbd.BOOKSET_ID = #{booksetId}

		       group by tbd.BOOKSET_ID ,tbd.HAPPEN_DATE
		     ) MAX_SEQ
		     WHERE t.Book_Order = MAX_SEQ.bookOrder
		     AND t.bookset_id = MAX_SEQ.booksetId
		     AND t.happen_date = MAX_SEQ.happenDate

		     	and t.VAT_TYPE = #{vatType}


   				and t.TAX_P_TYPE = #{taxPType}


   				and t.CALC_TYPE = #{calcType}


   				and t.FEE_TYPE = #{feeType}

	select t.*
	FROM TAX_BOK_BALANCE_SUM t,
		(select max(TBBS.BOOK_ORDER) AS bookOrder,
		       TBBS.BOOKSET_ID as booksetId,
		       TBBS.HAPPEN_DATE as happenDate
		from TAX_BOK_BALANCE_SUM TBBS
		where TBBS.BOOK_DATE <= #{endDate}

   			and TBBS.happen_date = #{endDate}


   			and TBBS.BOOKSET_ID = #{booksetId}

		group by TBBS.BOOKSET_ID,TBBS.HAPPEN_DATE
		) MAX_SEQNO
		where t.Book_Order = MAX_SEQNO.bookOrder
	     AND t.bookset_id = MAX_SEQNO.booksetId
	     AND t.happen_date = MAX_SEQNO.happenDate

	     and t.VAT_TYPE = #{vatType}


	     	and t.TAX_P_TYPE = #{taxPType}

select sum(A1) as a1, sum(B1) as b1, sum(A2) as a2, sum(B2) as b2, sum(B3) as b3, sum(FREE_36FILE) as free36file, sum(FREE_46FILE) as free46file, sum(FREE_70FILE) as free70file, sum(FREE_SEC) as freeSec, sum(C1) as c1, sum(C2) as c2, sum(C3) as c3, sum(C4) as c4, sum(C5) as c5, sum(E1) as e1, sum(E2) as e2, sum(E3) as e3 from TAX_DECLARE_SUM_INFO tdsi where tdsi.declare_year = #{declareYear} and tdsi.declare_date = #{declareDate}
and (tdsi.SUBJECT_NATURE in
null) OR tdsi.SUBJECT_NATURE in(
#{booksetId}
)
and tdsi.sign_flag = #{signFlag}

select BB.BOOKSET_ID as booksetId, BB.END_DATE as endDate, BBD.BOOKSET_DATE as booksetDate, fpt.PROFIT_FLAG as signFlag from BOK_BOOKSET BB
inner join BOK_BOOKSET_DATE BBD on BBD.BOOKSET_ID = BB.BOOKSET_ID
inner join FIN_PRODUCT FP on FP.FINPROD_ID = BB.ACCT_SUBJECT_ID and FP.FINPROD_TYPE = #{finprodType}
inner join FIN_PRODUCT_ADD fpt on FP.FINPROD_ID = fpt.finprod_id
inner join FIN_CASH_INFO FCI on FP.FINPROD_ID=FCI.FINPROD_ID
AND FCI.CASH_TYPE_2 IN (#{cashType2}) WHERE BB.ACCT_SUBJECT_TYPE = #{acctSubjectType} and BB.END_DATE > #{declareStart,jdbcType=DATE}

select #{name} as finprodName, ti.A1,/**应税利息及红利收入-不含税*/ ti.B1,/**利息及红利收入增值税*/ ti.A2,/**金融商品转让损益*/ ti.B2,/**金融商品转让增值税*/ ti.B3,/**金融商品转让入账增值税*/ ti.FREE_36FILE,/**免税收入-36号文件*/ ti.FREE_46FILE,/**免税收入-46号文件*/ ti.FREE_70FILE,/**免税收入-70号文件*/ ti.FREE_SEC,/**免税收入-国债及地方债*/ ti.C1,/**本期应交增值税产品划转到银行增值税*/ ti.C2,/**本期应交附加税费产品划转到银行附加税费*/ ti.C3,/**本期应交增值税银行划转到税局金融商品转让增值税*/ ti.C4,/**本期应交增值税银行划转到税局增值税*/ ti.C5,/**本期应交附加税费银行划转到税局附加税费*/ ti.E1,/**本期留存收益变动额*/ ti.E2,/**期初留存收益*/ ti.E3/**期末留存收益*/ from TAX_DECLARE_SUM_INFO ti left join BOK_BOOKSET bb on bb.bookset_id = ti.SUBJECT_NATURE
left join FIN_PRODUCT fp on fp.finprod_id = bb.ACCT_SUBJECT_ID where 1=1
and to_char(ti.DECLARE_YEAR,'YYYY') = #{declarYear}
and ti.DECLARE_DATE = #{declarDate}
and ti.DECLARE_TYPE = #{sumDimen}

		select 
		   count(0)
		from 
		    TAX_DECLARE_SUM_INFO ti
		where 1=1

   			and ti.SUBJECT_NATURE = #{subjectNature}


   			and ti.DECLARE_YEAR = #{declareYear}


   			and ti.DECLARE_DATE = #{declareDate}


   			and ti.DECLARE_TYPE = #{declareType}

mapper.delete:
	 	DELETE FROM TAX_DECLARE_SUM_INFO ti 
	 	WHERE ti.DECLARE_YEAR = #{declareYear}
	 	and ti.DECLARE_DATE = #{declareDate}
	 	and ti.DECLARE_TYPE = #{declareType}

   			and ti.SUBJECT_NATURE = #{subjectNature}
